import{_ as l,o as e,c as i,a2 as t}from"./chunks/framework.CHeM0PsO.js";const _=JSON.parse('{"title":"竞争分析","description":"","frontmatter":{},"headers":[],"relativePath":"skill/compete_analysis.md","filePath":"skill/compete_analysis.md","lastUpdated":null}'),o={name:"skill/compete_analysis.md"};function r(s,a,n,h,d,c){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="竞争分析" tabindex="-1">竞争分析 <a class="header-anchor" href="#竞争分析" aria-label="Permalink to &quot;竞争分析&quot;">​</a></h1><h2 id="竞品思维误区" tabindex="-1">竞品思维误区 <a class="header-anchor" href="#竞品思维误区" aria-label="Permalink to &quot;竞品思维误区&quot;">​</a></h2><ol><li>你所以为的竞品，以为是领导，只是自己认为的竞品，别人根本没把你当竞品。</li><li>只把关注点集中在了那几个竞争对手上，而企业的竞争是多方面的，复杂的。</li><li>运用竞争研究资料时，自己反而会有意无意的模仿。</li></ol><h2 id="竞争思维" tabindex="-1">竞争思维 <a class="header-anchor" href="#竞争思维" aria-label="Permalink to &quot;竞争思维&quot;">​</a></h2><p>企业之间也是如此，当发生竞争的时候，彼此的利益就会发生转移，是在抢夺利益。</p><p>当用竞争思维去分析时，就不会去把关注点全集中在那几个头部品牌的表面分析上，会更深入的研究竞争者和竞争局面。这才是研究竞争的真正意义。</p><p>用竞争思维去研究的时候，自然就会看那些真正跟自己形成竞争的品牌，关注竞争对手同时，也看整个大局。</p><p>所以我说是做竞争研究分析，不做竞品研究分析。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><p>6个要点</p><ol><li>行业的总体竞争态势；</li><li>画竞争地图；</li><li>行业领导者梳理；</li><li>识别核心竞争者（细分出竞争能力：资金、渠道、产品技术、品牌）；</li><li>识别核心竞争者的传播策略；</li><li>识别异军突起的企业；</li></ol><h2 id="美团-2" tabindex="-1">美团 <a href="https://www.bilibili.com/video/BV1wz4y1y7sg?p=5" target="_blank" rel="noreferrer">2</a> <a class="header-anchor" href="#美团-2" aria-label="Permalink to &quot;美团 [2]&quot;">​</a></h2><ol><li>将有限资源投放在二线城市市场，最后杀回一线</li><li>制空权：线上时o2o的入口，看出C端用户规模时关键</li><li>看重用户体验、留住用户。</li></ol><h2 id="竞争战略" tabindex="-1">竞争战略 <a class="header-anchor" href="#竞争战略" aria-label="Permalink to &quot;竞争战略&quot;">​</a></h2><p>行业内：领先者、跟随者、新加入者</p><ul><li>差异化：淘宝（C2C、性价比）、京东（B2C、配送快、购物体验好）、美丽说蘑菇街（女性电商导购到淘宝）、拼多多（拼一刀、货找人）</li><li>跟随：慧聪网跟随淘宝</li><li>成本优势：京东VS苏宁国美：偏远郊区来仓储VS闹市门店来摆卖</li><li>免费：360VS金山瑞星卡巴斯基，互联网思维：培养用户来赚钱VS软件思维：付软件。</li><li>好人/坏人：囚徒困境，好人+以牙还牙。</li></ul><h2 id="swot分析" tabindex="-1">SWOT分析 <a class="header-anchor" href="#swot分析" aria-label="Permalink to &quot;SWOT分析&quot;">​</a></h2><p>别高估自己、低估对手！</p>',18)])])}const u=l(o,[["render",r]]);export{_ as __pageData,u as default};
